package net.fabricmc.fabric.api.event.lifecycle.v1;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;

/** Fabric API: server worlds loading/unloading (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
public final class ServerWorldEvents {
    private ServerWorldEvents() {}

    public static final Event<Load> LOAD = EventFactory.createArrayBacked(Load.class, ls -> (server, world) -> { for (Load l : ls) l.onWorldLoad(server, world); });
    public static final Event<Unload> UNLOAD = EventFactory.createArrayBacked(Unload.class, ls -> (server, world) -> { for (Unload l : ls) l.onWorldUnload(server, world); });

    @FunctionalInterface public interface Load { void onWorldLoad(MinecraftServer server, ServerLevel world); }
    @FunctionalInterface public interface Unload { void onWorldUnload(MinecraftServer server, ServerLevel world); }
}
